const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',box:'<path d="m3 7 9-4 9 4v11l-9 4-9-4Z M3 7l9 4 9-4 M12 11v11"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3 M16 5a3 3 0 0 1 0 6 M18 15a5 5 0 0 1 3 6"/>',check:'<path d="m6 12 4 4 8-8"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',pause:'<path d="M9 7v10 M15 7v10"/><circle cx="12" cy="12" r="9"/>',plus:'<path d="M12 5v14 M5 12h14"/>',tv:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8 M12 17v4"/>',out:'<path d="M9 4H4v16h5 M12 12h9 m-4-4 4 4-4 4"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.box}</svg>`;
const statuses=['Concluído','Em andamento','Em espera']; const cls=s=>s==='Concluído'?'done':s==='Em andamento'?'andamento':'espera';const badge=s=>`<span class="badge ${cls(s)}">${s}</span>`;
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'});const fmt=d=>d?new Date(d+'T12:00:00').toLocaleDateString('pt-BR'):'—';
let db;try{db=JSON.parse(localStorage.getItem('bancada-v1'))}catch{}if(!db){db={users:[{name:'Administrador',login:'admin',password:'admin',role:'Administrador'}],lots:[],tvs:[]};const specs=[['Centro de distribuição · São Paulo',6,'Em andamento'],['Loja parceira · Campinas',4,'Em espera'],['Centro de distribuição · Santos',5,'Concluído'],['Loja parceira · Sorocaba',3,'Em andamento'],['Centro de distribuição · São Paulo',4,'Concluído']];specs.forEach(([origin,n,status],i)=>{const id='LT-'+String(i+1).padStart(4,'0');db.lots.push({id,origin,date:`2026-10-${String(12+i%4).padStart(2,'0')}`,notes:''});for(let j=0;j<n;j++)db.tvs.push({id:crypto.randomUUID(),lot:id,model:['55UR8750PSA','43LR6700PSA','50UT8050PSA','65QNED80SRA'][j%4],serial:`LG26${i+1}00${j+1}`,os:`2026${i+1}0${j+1}`,client:'Equipamento de demonstração',defect:['Sem imagem','Não liga','Sem áudio','Linhas na tela'][j%4],status,entry:`2026-10-${String(12+i%4).padStart(2,'0')}`,exit:status==='Concluído'?'2026-10-16':''})});save()}
function save(){localStorage.setItem('bancada-v1',JSON.stringify(db))}let current=db.users.find(u=>u.login===sessionStorage.getItem('bancada-user')),page='dashboard',filter='Todos',query='',selected=null;const lotTVs=id=>db.tvs.filter(t=>t.lot===id);function lotStatus(id){const ts=lotTVs(id);return ts.length&&ts.every(t=>t.status==='Concluído')?'Concluído':ts.some(t=>t.status==='Em andamento')?'Em andamento':'Em espera'}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function login(){resetResponsiveMenu();current=null;$('#app').innerHTML=`<div class="login"><section class="loginart"><div class="brand"><span class="brandmark">b.</span>Bancada</div><div><div class="eyebrow" style="color:#94bea5">GESTÃO DE ASSISTÊNCIA TÉCNICA</div><h1>Cada TV no lugar certo.<br>Cada serviço sob controle.</h1><p>Da entrada à entrega, acompanhe sua operação com clareza e mantenha sua equipe em sintonia.</p></div><small style="color:#a1b9ac">Manutenção de televisores • Multimarcas</small></section><section class="loginform"><form class="loginbox" id="login"><div class="eyebrow">BEM-VINDO À BANCADA</div><h2>Acesse sua operação</h2><p>Entre com suas credenciais para acompanhar os serviços de manutenção.</p><label>Usuário<input name="login" autocomplete="username" placeholder="Seu usuário" required></label><label>Senha<input name="password" type="password" autocomplete="current-password" placeholder="Sua senha" required></label><p class="error" id="loginerror" role="alert"></p><button class="btn primary">Entrar na console <span>→</span></button><p class="note">Ambiente de demonstração<br>Usuário: <b>admin</b> &nbsp; Senha: <b>admin</b><br>Os dados desta prévia ficam salvos neste navegador.</p></form></section></div>`;$('#login').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);current=db.users.find(u=>u.login===f.get('login').trim()&&u.password===f.get('password'));if(!current){$('#loginerror').textContent='Usuário ou senha incorretos.';return}sessionStorage.setItem('bancada-user',current.login);render()}}
function go(p,f='Todos'){page=p;filter=f;query='';selected=null;render()}
function render(){resetResponsiveMenu();if(!current)return login();$('#app').innerHTML=`<div class="shell"><button class="menu-overlay" id="menu-overlay" tabindex="-1" hidden aria-label="Fechar menu"></button><aside class="sidebar" id="sidenav" aria-label="Menu principal"><div class="sidebar-heading"><div class="brand"><span class="brandmark">b.</span><div>Bancada<small>Service management</small></div></div><button class="menu-close" id="menu-close" aria-label="Fechar menu">✕</button></div><div class="navlabel">PRINCIPAL</div><nav>${[['dashboard','grid','Visão geral'],['lots','box','Lotes de serviço'],['finance','box','Controladoria'],['catalog','box','Catálogo de serviços'],...(current.role==='Administrador'?[['users','users','Usuários']]:[])].map(([p,i,t])=>`<button class="nav ${page===p?'active':''}" data-page="${p}">${icon(i)}${t}</button>`).join('')}</nav><div class="sidebarbottom"><div class="operation-label">Assistência multimarcas</div><p>Controle de serviços de televisores</p><p style="font-size:10px;margin-top:12px">Bancada v1.0 · Prévia de testes</p></div></aside><main id="app-main"><header class="topbar"><div class="topbar-start"><button class="menu-toggle" id="menu-toggle" aria-label="Abrir menu" aria-controls="sidenav" aria-expanded="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg></button><span>Workspace &nbsp; / &nbsp; <b style="color:#425448">Assistência técnica</b><span class="demo">DEMONSTRAÇÃO</span></span></div><div class="profile"><span class="avatar">${esc(current.name.slice(0,2).toUpperCase())}</span><div><b style="font-size:12px">${esc(current.name)}</b><small style="display:block;font-size:10px;margin-top:3px">${esc(current.role)}</small></div><button id="logout" title="Sair" aria-label="Sair">${icon('out')}</button></div></header><div class="content" id="content"></div></main></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#logout').onclick=()=>{sessionStorage.removeItem('bancada-user');login()};if(page==='catalog')serviceCatalogPage();else if(page==='finance')controladoria();else if(page==='users')users();else if(selected)detail();else if(page==='lots')lots();else dashboard();setupResponsiveMenu()}
function heading(title,desc,action){return `<div class="heading"><div><div class="eyebrow">CONTROLE DE PRODUÇÃO</div><h1>${title}</h1><p>${desc}</p></div>${action||''}</div>`}const newlotbtn=()=>`<button class="btn primary" id="newlot">${icon('plus')} Novo lote</button>`;
function dashboard(){const counts=statuses.map(s=>db.tvs.filter(t=>t.status===s).length),total=db.tvs.length,rate=total?Math.round(counts[0]/total*100):0;$('#content').innerHTML=heading('Sua operação, em um só lugar.','Acompanhe o fluxo de serviços e o desempenho da sua bancada.',newlotbtn())+`<div class="stats">${statuses.map((s,i)=>`<button class="stat ${['green','blue','amber'][i]}" data-status="${s}"><div class="stathead">Serviços ${['concluídos','em andamento','em espera'][i]}<span class="statusicon">${icon(['check','clock','pause'][i])}</span></div><strong>${String(counts[i]).padStart(2,'0')}</strong><div class="statfoot"><span>${['Prontos para entrega','Em manutenção na bancada','Aguardando início ou peças'][i]}</span><span>Ver lotes ↗</span></div></button>`).join('')}</div><div class="overview"><section class="panel"><div class="panelhead"><div><h2>Distribuição dos serviços</h2><p>Visão atual de todos os equipamentos</p></div><span class="subtle">${total} televisores</span></div><div class="bars">${statuses.map((s,i)=>`<div class="barrow"><span>${s}</span><div class="track"><div class="fill" style="width:${total?counts[i]/total*100:0}%;background:${['#4d9671','#7199d6','#dfbd64'][i]}"></div></div><b>${counts[i]}</b></div>`).join('')}</div><p class="legend">Status atualizado a partir das TVs registradas nos lotes.</p></section><section class="panel"><div class="panelhead"><div><h2>Panorama da operação</h2><p>Da entrada à conclusão</p></div>${icon('tv')}</div><div class="summary"><div class="ring"><strong>${rate}%</strong></div><p><strong>Serviços concluídos</strong><br>${counts[0]} de ${total} TVs finalizadas<br>em ${db.lots.length} lotes registrados.</p></div></section></div><div class="tabletitle"><h2>Lotes recentes <small style="font-size:12px;font-weight:400;margin-left:8px">${db.lots.length} registrados</small></h2><button class="link" id="alllots">Ver todos os lotes →</button></div><section class="panel">${lotTable(db.lots.slice().reverse().slice(0,5))}</section><p class="muted" style="font-size:10px;margin-top:17px">Dados ilustrativos para teste • As alterações são salvas automaticamente neste navegador.</p>`;$('#newlot').onclick=newLot;$('#alllots').onclick=()=>go('lots');document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>go('lots',b.dataset.status));bindLots()}
function lotTable(ls){return `<div class="tablewrap"><table class="lot-table"><thead><tr><th>LOTE / ORIGEM</th><th>DATA DE ENTRADA</th><th>EQUIPAMENTOS</th><th>STATUS DO LOTE</th><th></th></tr></thead><tbody>${ls.map(l=>`<tr><td><b>${esc(l.id)}</b><small>${esc(l.origin)}</small></td><td>${fmt(l.date)}</td><td>${lotTVs(l.id).length} TVs</td><td>${badge(lotStatus(l.id))}</td><td><div class="row-actions"><button class="link" data-lot="${esc(l.id)}">Abrir lote ↗</button><button class="link" data-doc-kind="OS" data-doc-scope="lot" data-doc-id="${esc(l.id)}">Gerar OS</button><button class="link" data-doc-kind="NF" data-doc-scope="lot" data-doc-id="${esc(l.id)}">Gerar nota</button></div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nenhum lote encontrado.</td></tr>'}</tbody></table></div><div class="footer"><span>${ls.length} lote(s) exibido(s)</span><span>Bancada • Controle de serviços</span></div>`}
function bindLots(){document.querySelectorAll('[data-lot]').forEach(b=>b.onclick=()=>{selected=b.dataset.lot;page='lots';render()});bindDocumentActions()}
function lots(){const ls=db.lots.slice().reverse().filter(l=>(filter==='Todos'||lotTVs(l.id).some(t=>t.status===filter))&&(`${l.id} ${l.origin} ${lotTVs(l.id).map(t=>t.serial+' '+t.os+' '+t.model).join(' ')}`.toLowerCase().includes(query.toLowerCase())));$('#content').innerHTML=heading('Lotes de serviço','Organize as entradas e acompanhe cada equipamento até a entrega.',newlotbtn())+`<section class="panel"><div class="tools"><div class="tabs">${['Todos',...statuses].map(s=>`<button class="tab ${filter===s?'active':''}" data-filter="${s}">${s}</button>`).join('')}</div><input class="search" id="search" aria-label="Buscar lotes" placeholder="Buscar lote, origem, OS ou série..." value="${esc(query)}"></div>${lotTable(ls)}</section><p class="muted" style="font-size:11px;margin-top:14px">Os filtros mostram lotes que contêm TVs no status selecionado. O status do lote resume todos os equipamentos.</p>`;$('#newlot').onclick=newLot;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;lots()});$('#search').oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;lots();$('#search').focus();$('#search').setSelectionRange(pos,pos)};bindLots()}
function showModal(title,body,onSubmit){$('#modal').innerHTML=`<div class="modalhead"><h2>${title}</h2><button type="button" id="closemodal" aria-label="Fechar">✕</button></div><form id="form">${body}<p class="error" id="formerror" role="alert"></p><div class="actions"><button type="button" class="btn" id="cancel">Cancelar</button><button class="btn primary">Salvar registro</button></div></form>`;$('#closemodal').onclick=$('#cancel').onclick=()=>$('#modal').close();$('#form').onsubmit=e=>{e.preventDefault();onSubmit(Object.fromEntries(new FormData(e.target)))};$('#modal').showModal()}
function newLot(){showModal('Novo lote de serviço',`<label>Origem / identificação do lote<input name="origin" required maxlength="100" placeholder="Ex.: Loja Centro — remessa 01"></label><label>Data de entrada<input type="date" name="date" value="${today()}" required></label><label>Observações<textarea name="notes" maxlength="1000" placeholder="Informações sobre esta remessa"></textarea></label>`,f=>{const origin=f.origin.trim();if(!origin){$('#formerror').textContent='Informe uma origem válida.';return}const n=Math.max(0,...db.lots.map(l=>Number(l.id.split('-')[1])))+1;const l={...f,origin,id:'LT-'+String(n).padStart(4,'0')};db.lots.push(l);save();$('#modal').close();selected=l.id;page='lots';render();toast('Lote criado. Agora cadastre as TVs.')})}
function detail(){const l=db.lots.find(l=>l.id===selected),ts=lotTVs(selected);$('#content').innerHTML=`<button class="link detailback" id="back">← Voltar aos lotes</button>`+heading(esc(l.id),esc(l.origin),`<div class="document-actions"><button class="btn" data-doc-kind="OS" data-doc-scope="lot" data-doc-id="${esc(l.id)}">Gerar OS do lote</button><button class="btn" data-doc-kind="NF" data-doc-scope="lot" data-doc-id="${esc(l.id)}">Gerar nota do lote</button><button class="btn primary" id="newtv">${icon('plus')} Adicionar TV</button></div>`)+`<div class="detailstats"><span>Entrada: ${fmt(l.date)}</span><span>•</span><span>${ts.length} equipamentos</span>${badge(lotStatus(l.id))}</div>${l.notes?`<p style="font-size:13px;margin-bottom:20px">${esc(l.notes)}</p>`:''}<section class="panel"><div class="panelhead"><div><h2>Televisores do lote</h2><p>Atualize o serviço e registre a saída de cada equipamento.</p></div></div><div class="tablewrap"><table><thead><tr><th>TV / NÚMERO DE SÉRIE</th><th>ORDEM DE SERVIÇO</th><th>DEFEITO</th><th>STATUS</th><th>ENTRADA / SAÍDA</th><th></th></tr></thead><tbody>${ts.map(t=>`<tr><td><b>${esc(t.model)}</b><small>S/N ${esc(t.serial)}</small></td><td>${esc(t.os)}<small>${esc(t.client)}</small></td><td>${esc(t.defect)}</td><td>${badge(t.status)}</td><td>${fmt(t.entry)}<small>Saída: ${fmt(t.exit)}</small></td><td><div class="row-actions"><button class="link" data-edit="${t.id}">Editar →</button><button class="link" data-doc-kind="OS" data-doc-scope="device" data-doc-id="${t.id}">Gerar OS</button><button class="link" data-doc-kind="NF" data-doc-scope="device" data-doc-id="${t.id}">Gerar nota</button></div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Este lote ainda não tem TVs. Adicione o primeiro equipamento.</td></tr>'}</tbody></table></div></section>`;$('#back').onclick=()=>go('lots',filter);$('#newtv').onclick=()=>editTV();document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editTV(b.dataset.edit));bindDocumentActions()}
function editTV(id){const t=db.tvs.find(t=>t.id===id)||{model:'',serial:'',os:'',client:'',defect:'',status:'Em espera',entry:today(),exit:''};const inp=(name,title,type='text',required=true)=>`<label>${title}<input name="${name}" type="${type}" value="${esc(t[name])}" ${required?'required':''} maxlength="120"></label>`;showModal(id?'Editar equipamento':'Registrar TV',`<div class="formgrid">${inp('model','Marca e modelo')}${inp('serial','Número de série')}${inp('os','Ordem de serviço')}${inp('client','Cliente / referência','text',false)}${inp('entry','Data de entrada','date')}${inp('exit','Data de saída','date',false)}</div><label>Defeito informado<textarea name="defect" required maxlength="500">${esc(t.defect)}</textarea></label><label>Status do serviço<select name="status">${statuses.map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select></label><label>Observações / serviços executados<textarea name="serviceNotes" maxlength="3000" rows="4" placeholder="Descreva os serviços realizados, peças substituídas e testes executados.">${esc(t.serviceNotes)}</textarea></label><small>A conclusão da manutenção não registra a saída automaticamente. Preencha a data de saída na entrega.</small>`,f=>{for(const k of ['model','serial','os','defect']){f[k]=f[k].trim();if(!f[k]){$('#formerror').textContent='Preencha os campos obrigatórios.';return}}if(db.tvs.some(v=>v.id!==id&&(v.serial.toLowerCase()===f.serial.toLowerCase()||v.os.toLowerCase()===f.os.toLowerCase()))){$('#formerror').textContent='Já existe uma TV com esta série ou ordem de serviço.';return}if(f.exit&&(f.exit<f.entry||f.status!=='Concluído')){$('#formerror').textContent='A saída deve ser posterior à entrada e o serviço deve estar concluído.';return}if(id)Object.assign(t,f);else db.tvs.push({...f,id:crypto.randomUUID(),lot:selected});save();$('#modal').close();render();toast('Equipamento salvo com sucesso.')})}
function users(){if(current.role!=='Administrador')return go('dashboard');$('#content').innerHTML=heading('Usuários da console','Gerencie quem pode acessar sua operação.',`<button class="btn primary" id="newuser">${icon('plus')} Novo usuário</button>`)+`<section class="panel"><div class="tablewrap"><table><thead><tr><th>NOME</th><th>USUÁRIO</th><th>PERFIL</th></tr></thead><tbody>${db.users.map(u=>`<tr><td><b>${esc(u.name)}</b></td><td>${esc(u.login)}</td><td>${esc(u.role)}</td></tr>`).join('')}</tbody></table></div></section><p class="note">Login de demonstração, armazenado no navegador. Use senhas fictícias nesta prévia. Usuários operacionais podem gerenciar lotes e TVs; apenas administradores criam usuários.</p>`;$('#newuser').onclick=()=>showModal('Criar usuário',`<label>Nome completo<input name="name" required maxlength="80"></label><label>Usuário<input name="login" required pattern="[a-zA-Z0-9._-]+" maxlength="40" autocomplete="off"></label><label>Senha de teste<input name="password" required type="password" minlength="4" autocomplete="new-password"></label><label>Perfil<select name="role"><option>Operacional</option><option>Administrador</option></select></label>`,f=>{f.name=f.name.trim();f.login=f.login.trim().toLowerCase();if(!f.name||db.users.some(u=>u.login.toLowerCase()===f.login)){$('#formerror').textContent='Informe um nome e um usuário ainda não cadastrado.';return}db.users.push(f);save();$('#modal').close();users();toast('Usuário criado. Já pode entrar na console.')})}
render();

function bindDocumentActions(){document.querySelectorAll('[data-doc-kind]').forEach(b=>b.onclick=()=>financeQuickDocument(b.dataset.docKind,b.dataset.docScope,b.dataset.docId))}
